"use strict";

const PlayerPlus = (() => {
  const STYLE_ID = "zoidium-player-plus-style";
  const QUALITY_STORAGE_KEY = "zoidium.player-plus.quality";
  const QUALITY_OPTIONS = [
    { value: 1, label: "Full quality" },
    { value: 0.5, label: "1/2 quality" },
    { value: 0.25, label: "1/4 quality" },
    { value: 0.125, label: "1/8 quality" },
  ];
  const SPEED_OPTIONS = [0, 0.25, 0.5, 0.75, 1, 1.25, 1.5, 2];
  const state = {
    active: false,
    installation: null,
    editor: null,
    PZ: null,
    document: null,
    window: null,
    toolbar: null,
    pauseButton: null,
    pauseIcon: null,
    renderOnceButton: null,
    qualitySelect: null,
    adaptiveButton: null,
    adaptiveLimit: null,
    adaptive: null,
    adaptiveModule: null,
    adaptiveSettings: null,
    effectiveQuality: 1,
    timingViewport: null,
    speedSelect: null,
    speedChanged: null,
    toolbarObserver: null,
    layoutObservers: [],
    layoutFrame: 0,
    style: null,
    quality: 1,
    paused: false,
    viewports: new Set(),
    viewportPrototype: null,
    originalRenderPipeline: null,
    patchedRenderPipeline: null,
    originalResize: null,
    patchedResize: null,
  };

  // Other plugins may retain our wrapper after an out-of-order disable.
  // Each installation owns its callback and cannot become active again.
  const PATCH = Symbol.for("zoidium.inactivePatch");

  function unwrapInactivePatch(callback) {
    while (callback?.[PATCH] && !callback[PATCH].installation.active) {
      callback = callback[PATCH].original;
    }
    return callback;
  }

  function guardPatch(target, key, handler, original) {
    const installation = state.installation;
    const wrapper = function () {
      if (!installation.active) {
        const callback = unwrapInactivePatch(original);
        if (target[key] === wrapper) target[key] = callback;
        return callback.apply(this, arguments);
      }
      return handler.apply(this, arguments);
    };
    wrapper[PATCH] = { installation, original };
    return wrapper;
  }

  function readStoredQuality() {
    // Storage may be blocked; fall back to the default quality.
    try {
      const value = Number(state.window?.localStorage?.getItem(QUALITY_STORAGE_KEY));
      return QUALITY_OPTIONS.some((option) => option.value === value) ? value : 1;
    } catch (_error) {
      return 1;
    }
  }

  function storeQuality(value) {
    try {
      state.window?.localStorage?.setItem(QUALITY_STORAGE_KEY, String(value));
    } catch (_error) {
      // The setting still applies for the current session if storage is blocked.
    }
  }

  function installStyle() {
    const existing = state.document.getElementById(STYLE_ID);
    if (existing) {
      state.style = existing;
      return;
    }
    const style = state.document.createElement("style");
    style.id = STYLE_ID;
    style.textContent = `
      .zoidium-player-plus-toolbar {
        display: flex !important;
        align-items: center;
        gap: 2px;
        overflow-x: auto;
        padding: 5px !important;
        position: absolute !important;
      }

      .zoidium-player-plus-toolbar > * {
        flex-shrink: 0;
      }

      .zoidium-player-plus-toolbar > button {
        box-sizing: border-box;
        margin: 0 !important;
        padding: 0 !important;
        width: 29px;
      }

      .zoidium-player-plus-toolbar > span {
        width: var(--zoidium-player-plus-space, 8px) !important;
      }

      .zoidium-player-plus-pause,
      .zoidium-player-plus-render-once {
        background: transparent !important;
        border: 2px solid transparent !important;
        box-sizing: border-box;
        cursor: pointer;
        height: 29px !important;
        left: 5px;
        margin: 0 !important;
        padding: 0 !important;
        position: static !important;
        top: 5px;
        width: 30px;
      }

      .zoidium-player-plus-pause {
        left: 5px;
      }

      .zoidium-player-plus-render-once {
        left: 40px;
      }

      .zoidium-player-plus-pause:focus,
      .zoidium-player-plus-render-once:focus {
        border-color: var(--zui-accent) !important;
        outline: 0;
      }

      .zoidium-player-plus-render-once {
        height: 26px !important;
        width: 27px;
        top: 6px;
      }

      .zoidium-player-plus-pause svg,
      .zoidium-player-plus-render-once svg {
        fill: var(--zui-text-muted);
        height: 25px;
        pointer-events: none;
        width: 25px;
      }

      .zoidium-player-plus-render-once svg {
        height: 23px;
        width: 23px;
      }

      .zoidium-player-plus-pause.is-paused svg {
        fill: var(--zui-value);
      }

      .zoidium-player-plus-adaptive,
      .zoidium-player-plus-limit,
      .zoidium-player-plus-speed,
      .zoidium-player-plus-quality {
        background-color: var(--zui-bg-input);
        border: 1px solid var(--zui-border);
        border-radius: 0;
        box-sizing: border-box;
        color: var(--zui-value);
        cursor: pointer;
        font-family: var(--zui-font);
        font-size: var(--zui-font-size-small);
        height: 27px;
        line-height: 25px;
        min-width: 112px;
        padding: 0 4px;
        position: static;
        order: 2;
        right: 5px;
        text-align: left;
        top: 6px;
        z-index: 2;
      }

      .zoidium-player-plus-toolbar > .zoidium-player-plus-adaptive {
        width: auto;
        padding: 0 6px !important;
        order: 2;
      }
      .zoidium-player-plus-adaptive[aria-pressed="true"] { border-color: var(--zui-accent); }
      .zoidium-player-plus-limit { min-width: 90px; }

      .zoidium-player-plus-speed {
        order: 1;
        min-width: 92px;
        width: 92px;
      }

      .zoidium-player-plus-speed:focus-visible,
      .zoidium-player-plus-quality:focus-visible {
        border-color: var(--zui-accent);
        outline: 0;
      }

      .zoidium-player-plus-speed option,
      .zoidium-player-plus-quality option {
        background-color: var(--zui-bg-input);
        color: var(--zui-text);
      }
    `;
    state.document.head.appendChild(style);
    state.style = style;
  }

  function findPlaybackToolbar() {
    if (!state.document) return null;
    const toolbars = state.document.querySelectorAll(".toolbarpanel");
    for (const toolbar of toolbars) {
      if (toolbar.querySelector('button[title="play (space)"]')) return toolbar;
    }
    return null;
  }

  function viewportConstructor() {
    return state.PZ?.ui?.viewport || null;
  }

  function registerViewport(viewport) {
    const constructor = viewportConstructor();
    if (!viewport || !constructor || !(viewport instanceof constructor)) return null;
    state.viewports.add(viewport);
    updateCacheBypass(viewport);
    if (!viewport.__zoidiumPlayerPlusFrame) {
      const originalFrame = viewport._renderFn;
      if (typeof originalFrame === "function") {
        const installation = state.installation;
        const guardedFrame = () => {
          if (!installation.active) return originalFrame();
          if (viewport.__zoidiumPlayerPlusPaused) {
            viewport.animFrameReq = null;
            return;
          }
          sampleAdaptive(viewport);
          return originalFrame();
        };
        viewport.__zoidiumPlayerPlusOriginalFrame = originalFrame;
        viewport.__zoidiumPlayerPlusFrame = guardedFrame;
        viewport._renderFn = guardedFrame;
      }
    }
    return viewport;
  }

  function getViewports() {
    const viewports = new Set(state.viewports);
    const constructor = viewportConstructor();
    if (constructor && state.document) {
      state.document.querySelectorAll("canvas").forEach((canvas) => {
        const panel = canvas.parentElement?.pz_panel;
        if (panel instanceof constructor) viewports.add(panel);
      });
    }
    return Array.from(viewports).map(registerViewport).filter(Boolean);
  }

  function applyQualityToViewport(viewport) {
    if (!viewport?.renderer || !viewport.canvas || !viewport.compositor || viewport.renderMode) return;
    const cssWidth = parseFloat(viewport.canvas.style.width) || viewport.canvas.clientWidth;
    const cssHeight = parseFloat(viewport.canvas.style.height) || viewport.canvas.clientHeight;
    if (!(cssWidth > 0) || !(cssHeight > 0)) return;

    const devicePixelRatio = state.window?.devicePixelRatio || 1;
    const width = Math.max(1, Math.round(cssWidth * devicePixelRatio * state.effectiveQuality));
    const height = Math.max(1, Math.round(cssHeight * devicePixelRatio * state.effectiveQuality));
    if (viewport.canvas.width !== width || viewport.canvas.height !== height) {
      viewport.renderer.setDrawingBufferSize(width, height, 1);
      viewport.compositor.setSize(viewport.canvas.width, viewport.canvas.height);
      if (viewport.camera) {
        viewport.camera.aspect = viewport.canvas.width / viewport.canvas.height;
        viewport.camera.updateProjectionMatrix();
      }
    }
  }

  function updateCacheBypass(viewport) {
    const reduced = state.effectiveQuality !== state.quality;
    if (reduced && !viewport.__zoidiumPlayerPlusCacheBypass) {
      viewport.__zoidiumPlayerPlusCacheBypass = { previous: viewport.__zoidiumImmediateOutput };
      viewport.__zoidiumImmediateOutput = true;
    } else if (!reduced && viewport.__zoidiumPlayerPlusCacheBypass) {
      viewport.__zoidiumImmediateOutput = viewport.__zoidiumPlayerPlusCacheBypass.previous;
      delete viewport.__zoidiumPlayerPlusCacheBypass;
    }
  }

  function applyQualityToAllViewports() {
    for (const viewport of getViewports()) applyQualityToViewport(viewport);
  }

  function updateAdaptiveLabel() {
    if (!state.qualitySelect) return;
    for (const option of state.qualitySelect.children) {
      const item = QUALITY_OPTIONS.find(entry => entry.value === Number(option.value));
      if (item) option.textContent = item.label;
    }
    const selected = Array.from(state.qualitySelect.children).find(option => Number(option.value) === state.quality);
    if (selected && state.effectiveQuality !== state.quality) {
      const effective = QUALITY_OPTIONS.find(option => option.value === state.effectiveQuality);
      selected.textContent = "Adaptive · " + effective.label.replace(" quality", "");
    }
  }

  function setEffectiveQuality(value) {
    if (state.effectiveQuality === value) return;
    state.effectiveQuality = value;
    applyQualityToAllViewports();
    updateAdaptiveLabel();
  }

  function resetAdaptive() {
    if (!state.adaptive) return;
    setEffectiveQuality(state.adaptive.reset(state.quality));
    for (const viewport of getViewports()) updateCacheBypass(viewport);
    updateAdaptiveLabel();
  }

  function sampleAdaptive(viewport) {
    if (!state.adaptive || viewport.renderMode || state.paused) return;
    if (!state.timingViewport) state.timingViewport = viewport;
    if (state.timingViewport !== viewport) return;
    const playback = viewport.editor?.playback || state.editor?.playback;
    const now = state.window.performance?.now?.() ?? Date.now();
    const value = state.adaptive.tick(now, {
      enabled: state.adaptiveSettings.enabled, playing: !!playback?.speed,
      chosen: state.quality, limit: state.adaptiveSettings.limit, fps: playback?.frameRate,
    });
    setEffectiveQuality(value);
  }

  function adaptiveStorage() {
    try { return state.window.localStorage; } catch (_error) { return null; }
  }

  function createAdaptiveControls(toolbar) {
    const button = state.document.createElement("button");
    button.type = "button";
    button.className = "zoidium-player-plus-adaptive";
    button.textContent = "Adaptive";
    button.title = "Adaptive preview quality";
    button.setAttribute("aria-pressed", String(state.adaptiveSettings.enabled));
    button.addEventListener("click", () => {
      state.adaptiveSettings.enabled = !state.adaptiveSettings.enabled;
      state.adaptiveModule.writeSetting(adaptiveStorage(), "enabled", state.adaptiveSettings.enabled);
      button.setAttribute("aria-pressed", String(state.adaptiveSettings.enabled));
      resetAdaptive();
    });
    const limit = state.document.createElement("select");
    limit.className = "pz-inputbox zoidium-player-plus-limit";
    limit.title = "Lowest adaptive quality";
    limit.setAttribute("aria-label", limit.title);
    for (const [value, label] of [["auto", "Lowest: Auto"], ["0.5", "Lowest: 1/2"], ["0.25", "Lowest: 1/4"], ["0.125", "Lowest: 1/8"]]) {
      const option = state.document.createElement("option");
      option.value = value; option.textContent = label; limit.appendChild(option);
    }
    limit.value = state.adaptiveSettings.limit;
    limit.addEventListener("change", () => {
      if (!["auto", "0.5", "0.25", "0.125"].includes(limit.value)) return;
      state.adaptiveSettings.limit = limit.value;
      state.adaptiveModule.writeSetting(adaptiveStorage(), "limit", limit.value);
      resetAdaptive();
    });
    toolbar.appendChild(button); toolbar.appendChild(limit);
    state.adaptiveButton = button; state.adaptiveLimit = limit;
  }

  function installViewportPatches() {
    const constructor = viewportConstructor();
    const prototype = constructor?.prototype;
    if (!prototype || state.viewportPrototype === prototype) return;
    state.viewportPrototype = prototype;

    const originalRenderPipeline = state.originalRenderPipeline = unwrapInactivePatch(prototype._render);
    state.patchedRenderPipeline = function () {
      registerViewport(this);
      if (this.__zoidiumPlayerPlusPaused) {
        if (this.__zoidiumPlayerPlusRenderOnce) {
          this.__zoidiumPlayerPlusRenderOnce = false;
        } else {
          if (this.animFrameReq != null) {
            state.window.cancelAnimationFrame(this.animFrameReq);
            this.animFrameReq = null;
          }
          return;
        }
      }
      return originalRenderPipeline.apply(this, arguments);
    };
    state.patchedRenderPipeline = guardPatch(prototype, "_render", state.patchedRenderPipeline, originalRenderPipeline);
    prototype._render = state.patchedRenderPipeline;

    const originalResize = state.originalResize = unwrapInactivePatch(prototype.resize);
    state.patchedResize = function () {
      registerViewport(this);
      const result = originalResize.apply(this, arguments);
      applyQualityToViewport(this);
      return result;
    };
    state.patchedResize = guardPatch(prototype, "resize", state.patchedResize, originalResize);
    prototype.resize = state.patchedResize;
  }

  function restoreViewportPatches() {
    const prototype = state.viewportPrototype;
    if (!prototype) return;
    if (prototype._render === state.patchedRenderPipeline) {
      prototype._render = state.originalRenderPipeline;
    }
    if (prototype.resize === state.patchedResize) prototype.resize = state.originalResize;
    for (const viewport of state.viewports) {
      updateCacheBypass(viewport);
      if (viewport.__zoidiumPlayerPlusFrame === viewport._renderFn) {
        viewport._renderFn = viewport.__zoidiumPlayerPlusOriginalFrame;
      }
      delete viewport.__zoidiumPlayerPlusFrame;
      delete viewport.__zoidiumPlayerPlusOriginalFrame;
      delete viewport.__zoidiumPlayerPlusPaused;
      delete viewport.__zoidiumPlayerPlusRenderOnce;
    }
    state.viewports.clear();
    state.viewportPrototype = null;
    state.originalRenderPipeline = null;
    state.patchedRenderPipeline = null;
    state.originalResize = null;
    state.patchedResize = null;
  }

  function setDrawingPaused(paused) {
    const next = Boolean(paused);
    state.paused = next;
    if (next) resetAdaptive();
    const viewports = getViewports();
    for (const viewport of viewports) {
      const wasPaused = viewport.__zoidiumPlayerPlusPaused === true;
      viewport.__zoidiumPlayerPlusPaused = next;
      if (next) {
        if (viewport.animFrameReq != null) {
          state.window.cancelAnimationFrame(viewport.animFrameReq);
          viewport.animFrameReq = null;
        }
      } else if (wasPaused && viewport.enabled && viewport.animFrameReq == null && typeof viewport._renderFn === "function") {
        viewport.animFrameReq = state.window.requestAnimationFrame(viewport._renderFn);
      }
    }
    updatePauseButton();
  }

  function updatePauseButton() {
    const button = state.pauseButton;
    if (!button) return;
    button.classList.toggle("is-paused", state.paused);
    button.setAttribute("aria-pressed", String(state.paused));
    button.title = state.paused ? "Resume drawing" : "Pause drawing";
    button.setAttribute("aria-label", button.title);
    if (state.pauseIcon && state.PZ?.ui?.switchIcon) {
      state.PZ.ui.switchIcon(state.pauseIcon, state.paused ? "play" : "pause");
      // CSS var() in an inline style follows the editor theme (see installStyle).
      state.pauseIcon.style.fill = state.paused ? "var(--zui-value)" : "var(--zui-text-muted)";
    }
  }

  function renderViewportOnce(viewport) {
    if (!viewport?.enabled || typeof viewport._render !== "function") return;
    const frame = viewport.editor?.playback?.currentFrame;
    viewport.__zoidiumPlayerPlusRenderOnce = true;
    try {
      viewport.widget2d?.update?.(frame);
      viewport.widget3d?.update?.(frame);
      viewport._render();
    } finally {
      viewport.__zoidiumPlayerPlusRenderOnce = false;
    }
  }

  function renderOnce() {
    resetAdaptive();
    for (const viewport of getViewports()) renderViewportOnce(viewport);
  }

  function createPauseButton(toolbar) {
    const button = state.document.createElement("button");
    button.className = "zoidium-player-plus-pause";
    button.type = "button";
    button.addEventListener("click", () => setDrawingPaused(!state.paused));
    const icon = state.PZ.ui.generateIcon("pause");
    button.appendChild(icon);
    toolbar.insertBefore(button, toolbar.firstElementChild);
    state.pauseButton = button;
    state.pauseIcon = icon;
    updatePauseButton();
  }

  function createRenderOnceButton(toolbar) {
    const button = state.document.createElement("button");
    button.className = "zoidium-player-plus-render-once";
    button.type = "button";
    button.title = "Render once";
    button.setAttribute("aria-label", button.title);
    button.addEventListener("click", renderOnce);
    const icon = state.PZ.ui.generateIcon("reset");
    button.appendChild(icon);
    toolbar.insertBefore(button, state.pauseButton?.nextSibling || toolbar.firstElementChild);
    state.renderOnceButton = button;
  }

  function createQualitySelect(toolbar) {
    const select = state.document.createElement("select");
    select.className = "pz-inputbox zoidium-player-plus-quality";
    select.title = "Preview quality";
    select.setAttribute("aria-label", "Preview quality");
    for (const option of QUALITY_OPTIONS) {
      const element = state.document.createElement("option");
      element.value = String(option.value);
      element.textContent = option.label;
      select.appendChild(element);
    }
    select.value = String(state.quality);
    select.addEventListener("change", () => {
      const value = Number(select.value);
      if (!QUALITY_OPTIONS.some((option) => option.value === value)) return;
      state.quality = value;
      resetAdaptive();
      storeQuality(value);
      applyQualityToAllViewports();
    });
    toolbar.appendChild(select);
    state.qualitySelect = select;
  }

  function updateSpeedSelect() {
    const select = state.speedSelect;
    if (!select) return;
    const speed = state.editor?.playback?.speed ?? 0;
    // J and L also select reverse and faster shuttle speeds.
    const values = SPEED_OPTIONS.includes(speed) ? SPEED_OPTIONS : [...SPEED_OPTIONS, speed];
    select.textContent = "";
    for (const value of values) {
      const option = state.document.createElement("option");
      option.value = String(value);
      option.textContent = value === 0 ? "Paused" : value + "x";
      select.appendChild(option);
    }
    select.value = String(speed);
  }

  function createSpeedSelect(toolbar) {
    const select = state.document.createElement("select");
    select.className = "pz-inputbox zoidium-player-plus-speed";
    select.title = "Playback speed";
    select.setAttribute("aria-label", "Playback speed");
    select.addEventListener("change", () => {
      const speed = Number(select.value);
      if (SPEED_OPTIONS.includes(speed) && state.editor?.playback) state.editor.playback.speed = speed;
    });
    toolbar.appendChild(select);
    state.speedSelect = select;
    updateSpeedSelect();
  }

  // CM3 centers its toolbar as text, which keeps play in the middle. The
  // flex layout keeps narrow toolbars scrollable, so the native separators on
  // each side of the transport buttons take the free space instead.
  // Widths for the separators before and after the transport buttons. The
  // measurements include the separators' current widths, which are removed
  // first. Without enough room, play moves as close to the center as fits.
  // Offset and client sizes are rounded to whole pixels while the controls
  // lay out at fractional widths, so filling the measured room exactly can
  // overflow by a fraction and show a scrollbar. One pixel stays free.
  function playSpaces({ width, right, before, after, playLeft, playWidth, padding = 5, base = 8, spare = 1 }) {
    const extraBefore = before - base, extraAfter = after - base;
    const slack = Math.max(0, Math.floor(width - padding - spare - (right - extraBefore - extraAfter)));
    const center = playLeft - extraBefore + playWidth / 2;
    // Whole pixels only: offsetLeft and offsetWidth are rounded, so a
    // fractional separator measures differently on the next pass and the
    // buttons shiver between two positions.
    const shift = Math.min(slack, Math.max(0, Math.round(width / 2 - center)));
    return [base + shift, base + slack - shift];
  }

  function centerPlayButton() {
    state.layoutFrame = 0;
    const toolbar = state.toolbar, Node = state.window?.Node;
    if (!toolbar?.isConnected || !Node) return;
    const children = Array.from(toolbar.children);
    const play = children.find(el => el.tagName === "BUTTON" && el.title === "play (space)");
    const spans = children.filter(el => el.tagName === "SPAN");
    const before = spans.filter(el => el.compareDocumentPosition(play) & Node.DOCUMENT_POSITION_FOLLOWING).pop();
    const after = spans.find(el => play && play.compareDocumentPosition(el) & Node.DOCUMENT_POSITION_FOLLOWING);
    if (!play || !before || !after) return;
    let right = 0;
    for (const el of children) if (el.offsetParent) right = Math.max(right, el.offsetLeft + el.offsetWidth);
    const widths = playSpaces({ width: toolbar.clientWidth, right, before: before.offsetWidth, after: after.offsetWidth,
      playLeft: play.offsetLeft, playWidth: play.offsetWidth });
    for (const [span, width] of [[before, widths[0]], [after, widths[1]]]) {
      // Keep the current width unless it is at least a pixel off, so rounding
      // in the next measurement can never start a back-and-forth.
      const current = parseFloat(span.style.getPropertyValue("--zoidium-player-plus-space"));
      if (Number.isFinite(current) && Math.abs(current - width) < 1) continue;
      span.dataset.zoidiumPlayerPlusSpace = "true";
      span.style.setProperty("--zoidium-player-plus-space", width + "px");
    }
  }

  function scheduleCentering() {
    if (!state.layoutFrame && state.window) state.layoutFrame = state.window.requestAnimationFrame(centerPlayButton);
  }

  function watchToolbarLayout(toolbar) {
    unwatchToolbarLayout();
    const win = state.window;
    if (!win?.MutationObserver || !win.Node) return;
    if (win.ResizeObserver) {
      const resize = new win.ResizeObserver(scheduleCentering);
      resize.observe(toolbar);
      state.layoutObservers.push(resize);
    }
    // Other plugins add, hide, and show toolbar buttons after Player+.
    // Our own separator widths are style changes too; reacting to them would
    // re-measure the layout we just set.
    const mutations = new win.MutationObserver((records) => {
      if (records.every(record => record.type === "attributes" && record.attributeName === "style" &&
        record.target?.dataset?.zoidiumPlayerPlusSpace === "true")) return;
      scheduleCentering();
    });
    mutations.observe(toolbar, { childList: true, subtree: true, attributes: true, attributeFilter: ["hidden", "style", "class"] });
    state.layoutObservers.push(mutations);
    scheduleCentering();
  }

  function unwatchToolbarLayout() {
    for (const observer of state.layoutObservers) observer.disconnect();
    state.layoutObservers = [];
    if (state.layoutFrame) state.window?.cancelAnimationFrame(state.layoutFrame);
    state.layoutFrame = 0;
  }

  function installControls(toolbar) {
    if (!toolbar) return;
    if (toolbar.dataset.zoidiumPlayerPlus === "true") {
      const pauseButton = toolbar.querySelector(".zoidium-player-plus-pause");
      const renderOnceButton = toolbar.querySelector(".zoidium-player-plus-render-once");
      const qualitySelect = toolbar.querySelector(".zoidium-player-plus-quality");
      const speedSelect = toolbar.querySelector(".zoidium-player-plus-speed");
      if (pauseButton && renderOnceButton && qualitySelect && speedSelect) {
        state.toolbar = toolbar;
        state.pauseButton = pauseButton;
        state.pauseIcon = pauseButton.querySelector("svg");
        state.renderOnceButton = renderOnceButton;
        state.qualitySelect = qualitySelect;
        state.speedSelect = speedSelect;
        updateSpeedSelect();
        updatePauseButton();
        watchToolbarLayout(toolbar);
        return;
      }
      delete toolbar.dataset.zoidiumPlayerPlus;
    }
    toolbar.dataset.zoidiumPlayerPlus = "true";
    toolbar.classList.add("zoidium-player-plus-toolbar");
    state.toolbar = toolbar;
    createPauseButton(toolbar);
    createRenderOnceButton(toolbar);
    createQualitySelect(toolbar);
    createAdaptiveControls(toolbar);
    createSpeedSelect(toolbar);
    applyQualityToAllViewports();
    watchToolbarLayout(toolbar);
  }

  function watchForToolbar() {
    const root = state.document.body || state.document.documentElement;
    if (!root) return;
    const install = () => {
      const toolbar = findPlaybackToolbar();
      if (!toolbar) return false;
      installControls(toolbar);
      state.toolbarObserver?.disconnect();
      state.toolbarObserver = null;
      return true;
    };
    if (install()) return;
    state.toolbarObserver = new MutationObserver(install);
    state.toolbarObserver.observe(root, { childList: true, subtree: true });
  }

  function removeControls() {
    unwatchToolbarLayout();
    if (state.toolbar) {
      for (const span of state.toolbar.querySelectorAll(":scope > span")) span.style.removeProperty("--zoidium-player-plus-space");
      state.toolbar.classList.remove("zoidium-player-plus-toolbar");
      delete state.toolbar.dataset.zoidiumPlayerPlus;
    }
    state.pauseButton?.remove();
    state.renderOnceButton?.remove();
    state.qualitySelect?.remove();
    state.adaptiveButton?.remove();
    state.adaptiveLimit?.remove();
    state.speedSelect?.remove();
    state.toolbar = null;
    state.pauseButton = null;
    state.pauseIcon = null;
    state.renderOnceButton = null;
    state.qualitySelect = null;
    state.adaptiveButton = null;
    state.adaptiveLimit = null;
    state.speedSelect = null;
  }

  async function activate(context) {
    if (state.active) return;
    state.active = true;
    const installation = state.installation = { active: true };
    context.lifecycle?.onDispose(() => {
      if (state.installation === installation) deactivate();
    });
    state.editor = context.editor;
    state.window = context.window || window;
    state.document = context.document || document;
    state.PZ = context.PZ || state.window.PZ;
    state.quality = readStoredQuality();
    const createRequire = context.apis?.modules?.createRequire || globalThis.ZoidiumPluginApis?.modules?.createRequire;
    state.adaptiveModule = createRequire ? createRequire(context.getAsset, { root: "./plugins/player-plus/" })("./adaptive-quality.js") : require("./adaptive-quality.js");
    let storage;
    try { storage = state.window.localStorage; } catch (_error) { storage = null; }
    state.adaptiveSettings = state.adaptiveModule.readSettings(storage);
    state.adaptive = state.adaptiveModule.createController();
    state.effectiveQuality = state.quality;
    state.speedChanged = () => { updateSpeedSelect(); if (!state.editor?.playback?.speed) resetAdaptive(); };
    state.editor?.playback?.onSpeedChanged?.watch(state.speedChanged);
    installStyle();
    installViewportPatches();
    watchForToolbar();
    // The initial project may finish sizing the viewport just after activation.
    state.window.requestAnimationFrame(() => {
      if (installation.active) applyQualityToAllViewports();
    });
  }

  function deactivate() {
    if (!state.active) return;
    state.active = false;
    state.installation.active = false;
    state.editor?.playback?.onSpeedChanged?.unwatch(state.speedChanged);
    state.speedChanged = null;
    state.toolbarObserver?.disconnect();
    state.toolbarObserver = null;
    setDrawingPaused(false);
    state.quality = 1;
    state.effectiveQuality = 1;
    applyQualityToAllViewports();
    removeControls();
    restoreViewportPatches();
    state.style?.remove();
    state.style = null;
    state.editor = null;
    state.PZ = null;
    state.document = null;
    state.window = null;
    state.quality = 1;
    state.paused = false;
    state.adaptive = null;
    state.adaptiveModule = null;
    state.adaptiveSettings = null;
    state.timingViewport = null;
  }

  return { activate, deactivate, playSpaces };
})();

module.exports = PlayerPlus;
